# Original Uzbek teaching notes, examples and exercises for the supplied curriculum.
L={}
def r(n,terms,code,task,pitfall,expected='',mode='web'):
 pairs=[v.replace('OR_OPERATOR','||').split('=',1) for v in terms.replace('||','OR_OPERATOR').split('|')]
 assert len(pairs)==5,(n,len(pairs))
 L[n]={'terms':pairs,'code':code,'task':task,'pitfall':pitfall,'expected':expected,'mode':mode}
r(1,'Frontend=Foydalanuvchi brauzerda ko‘radigan va boshqaradigan interfeys qismidir. U kontent, uslub va xatti-harakatni birlashtiradi.|Interfeys=Matn, navigatsiya, forma va tugmalar orqali inson bilan dastur aloqasini tashkil qiladi.|HTML=Kontent tuzilishi va ma’nosini belgilaydi; sarlavha bilan tugmaning vazifasi farqlanadi.|CSS=Rang, o‘lcham, joylashuv va turli ekranlarga mos ko‘rinishni boshqaradi.|JavaScript=Hodisalarga javob berish, ma’lumotni qayta ishlash va interfeysni o‘zgartirish imkonini beradi.', '<h1>Texnikum kutubxonasi</h1>\n<p>Kitoblarni topish va tanlash interfeysi.</p>\n<button>Kitoblarni ko‘rish</button>', 'Kutubxona sahifasining uchta foydalanuvchi vazifasini yozing; har vazifada HTML, CSS va JavaScript rolini ajrating.', 'Chiroyli ko‘rinishning o‘zi foydalanish qulayligi va ishlaydigan xizmatni kafolatlamaydi.')
r(2,'Internet=Ko‘plab tarmoqlarni bog‘lovchi infratuzilma; WWW uning ustida ishlaydigan xizmatlardan biridir.|WWW=Giperhavolalar bilan bog‘langan veb-resurslar tizimidir; Internet bilan aynan bir tushuncha emas.|Brauzer=Resurslarni so‘raydi, HTML va CSSni talqin qiladi, JavaScriptni bajaradi va sahifani ko‘rsatadi.|Server=So‘rovga javoban resurs yoki xizmat natijasini taqdim etadi; brauzer bilan vazifasi farqlanadi.|URL=Resurs manzili bo‘lib, sxema, host, yo‘l va qo‘shimcha qismlardan tuzilishi mumkin.', '<a href="https://developer.mozilla.org/">Veb qo‘llanma</a>\n<p>Manzil: https://example.com/kurs?til=uz#html</p>', 'Berilgan URLdagi sxema, host, yo‘l, query va fragmentni ajrating; brauzer–server so‘rov-javobini izohlang.', 'Brauzer ilovasi, qidiruv tizimi va Internetni bir-biriga tenglashtirmang.')
r(3,'Frontend=Brauzerda interfeysni tashkil qiladi; serverdan olingan natijani foydalanuvchiga ko‘rsatishi mumkin.|Backend=Serverdagi biznes qoidalari, ruxsatlar va ma’lumot bilan ishlashni bajaradi.|Tuzilma=HTML sahifadagi ma’noli elementlar va ularning o‘zaro joylashishini ifodalaydi.|Taqdimot=CSS tuzilmaning ko‘rinishini belgilaydi; kontentning ma’nosini almashtirmaydi.|Xatti-harakat=JavaScript foydalanuvchi harakatiga javob beradi; mijozdagi tekshiruv server tekshiruvini almashtirmaydi.', '<label>Email <input type="email" required></label>\n<button>Yuborish</button>', 'Ro‘yxatdan o‘tish jarayonini frontend va backend vazifalariga ajrating; interfeysda email maydoni yarating.', 'Parol yoki maxfiy API kalitini frontend kodida yashirish mumkin deb o‘ylamang.')
r(4,'Muharrir=Kod yozish, faylni saqlash va loyiha bo‘ylab ishlash vositasidir; brauzer vazifasini bajarmaydi.|Loyiha papkasi=Bir yechimga tegishli HTML, CSS, JavaScript va media fayllarni tartiblaydi.|index.html=Ko‘p statik hostinglarda bosh hujjat sifatida ishlatiladigan kelishilgan nomdir.|Nisbiy yo‘l=Resurs joylashuvini joriy hujjat manziliga nisbatan aniqlaydi; papka tuzilishiga bog‘liq.|DevTools=Brauzerning element, uslub, konsol va tarmoq holatini tekshirish vositalaridir.', '<!doctype html>\n<html lang="uz"><head><meta charset="UTF-8"><title>Birinchi loyiha</title></head>\n<body><h1>Salom, Frontend!</h1></body></html>', 'VS Code orqali loyiha papkasi, index.html va assets papkasini yarating; faylni saqlab brauzerda oching. Onlayn oynada shu HTMLni sinang.', 'Saqlanmagan tahrir yoki xato fayl yo‘li sabab eski natijani ko‘rish mumkin.')
r(5,'HTML=Gipermatnni belgilash tili bo‘lib, hujjat tuzilishi va semantikasini ifodalaydi.|DOCTYPE=Brauzerga standart HTML rejimini tanlash uchun beriladigan deklaratsiyadir.|html=Hujjatning asosiy ildiz elementi; lang atributi asosiy tilni bildiradi.|head=Kodlash, sarlavha va boshqa metama’lumotlar joylashadigan qismdir.|body=Foydalanuvchiga sahifada taqdim etiladigan asosiy kontent joylashadigan qismdir.', '<!doctype html>\n<html lang="uz">\n<head><meta charset="UTF-8"><title>Mening sahifam</title></head>\n<body><h1>O‘quv markazi</h1><p>Xush kelibsiz!</p></body>\n</html>', 'To‘liq HTML hujjati yarating; til, kodlash, sahifa nomi, h1 va paragrafni kiriting.', 'HTMLni hisoblash algoritmlarini bajaruvchi dasturlash tili sifatida ta’riflamang.')
r(6,'Teg=Element yozuvining ochuvchi yoki yopuvchi qismidir; barcha elementlarda yopuvchi teg mavjud emas.|Element=Boshlanishi, atributlari va mumkin bo‘lgan mazmuni bilan hujjatning bir bo‘lagini ifodalaydi.|Atribut=Elementga qo‘shimcha xususiyat yoki qiymat beradi; masalan, havolaning href manzili.|Ichma-ichlik=Ichki element tashqi elementning chegarasida to‘g‘ri joylashishi kerak.|Bo‘sh element=img va input kabi elementlar HTMLda ichki kontent va yopuvchi teg olmaydi.', '<section class="kurs">\n  <h2>HTML</h2>\n  <p><strong>Muhim:</strong> teglar tartibini saqlang.</p>\n</section>', 'section ichida sarlavha, paragraf va urg‘uli matn tuzing; uchta elementning teg va atributini izohlang.', 'Ichki elementni yopmasdan tashqi elementni yopish va har tegga yopuvchi juft qo‘shish xatodir.')
r(7,'Sarlavha=h1–h6 hujjatning mantiqiy bo‘lim darajalarini bildiradi; daraja faqat matn kattaligi uchun tanlanmaydi.|Paragraf=p mustaqil matn paragrafini ifodalaydi; brauzer oddiy bo‘shliqlarni odatda birlashtiradi.|br=Matndagi ma’noli satr uzilishini beradi, masalan manzilda.|hr=Mavzuviy uzilish yoki bo‘limlar orasidagi o‘tishni ifodalaydi.|Iyerarxiya=Sarlavhalar kontent tuzilmasini aks ettirishi va mantiqiy ketma-ketlikda tanlanishi kerak.', '<h1>Texnikum yangiliklari</h1>\n<h2>IT haftaligi</h2><p>Ochiq darslar bo‘lib o‘tadi.</p>\n<hr><h2>Manzil</h2><p>Namangan shahri<br>3-sonli texnikum</p>', 'Yangiliklar sahifasiga bitta asosiy sarlavha, ikki bo‘lim sarlavhasi va paragraflar qo‘shing.', 'Ko‘p br bilan sahifa maketi yoki katta bo‘shliq yaratmang; joylashuvni CSS bilan boshqaring.')
r(8,'strong=Mazmunning muhimligini semantik ravishda bildiradi; ko‘pincha qalin ko‘rinadi.|em=Gapdagi urg‘uni ifodalaydi; shunchaki qiyshiq shrift tanlash bilan bir xil emas.|b=Qo‘shimcha muhimlik bermasdan e’tiborni jalb qiluvchi matn bo‘lagi uchun ishlatiladi.|Belgi havolasi=&lt; va &amp; kabi yozuvlar HTMLda maxsus belgini matn sifatida ko‘rsatadi.|Semantika=Elementning vazifasi va ma’nosidir; tashqi ko‘rinish CSS orqali alohida boshqariladi.', '<p><strong>Muhim:</strong> topshiriqni <em>bugun</em> yuboring.</p>\n<p>HTMLda paragraf: &lt;p&gt;Matn&lt;/p&gt;</p>\n<p>Mualliflik belgisi: &copy; 2026</p>', 'Eslatma matniga muhimlik va urg‘u qo‘shing; teglarni bajariladigan kod emas, matn sifatida ko‘rsating.', 'strong va emni faqat bezak deb ishlatish element ma’nosini yo‘qotadi.')
r(9,'href=Havolaning manzilini belgilaydi; qiymat nisbiy yo‘l, mutlaq URL yoki fragment bo‘lishi mumkin.|Fragment=#belgi hujjatdagi mos idga o‘tish uchun ishlatiladi.|Nisbiy havola=Masalan, about.html joriy joylashuvga nisbatan boshqa hujjatni ko‘rsatadi.|Havola matni=Foydalanuvchiga havola maqsadini aytishi kerak; faqat shu yerga bosing deyish yetarli bo‘lmasligi mumkin.|Yangi oyna=target="_blank" boshqa kontekstni ochadi; xavfsiz odat sifatida rel="noopener" qo‘llanadi.', '<a href="#aloqa">Aloqa bo‘limi</a>\n<a href="https://developer.mozilla.org/" target="_blank" rel="noopener">MDN qo‘llanmasi</a>\n<section id="aloqa"><h2>Aloqa</h2><p>Bizga yozing.</p></section>', 'Ichki bo‘limga va tashqi qo‘llanmaga havola yarating; klaviatura bilan ikkala havolani sinang.', 'hrefdagi #nom bilan nishon element idsi bir xil bo‘lishi kerak.')
r(10,'src=Rasm resursining manzilini belgilaydi; noto‘g‘ri yo‘l rasmning ochilmasligiga olib keladi.|alt=Rasmning vazifasiga mos matnli muqobildir; ma’noli rasm mazmunini tushuntiradi.|Dekorativ rasm=Faqat bezak bo‘lsa alt="" ishlatilishi mumkin; ma’lumotli rasmga bu qoida ko‘r-ko‘rona qo‘llanmaydi.|O‘lcham=width va height tomonlar nisbatini oldindan ko‘rsatib, sahifa sakrashini kamaytirishga yordam beradi.|Moslashuv=CSS max-width:100% va height:auto rasmni konteynerga sig‘dirishda ishlatiladi.', '<img src="data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 width=%27300%27 height=%27120%27%3E%3Crect width=%27300%27 height=%27120%27 fill=%27%23176f58%27/%3E%3C/svg%3E" alt="Yashil rang namunasi" width="300" height="120">', 'Rasmli kurs kartasi yarating; alt mazmunini rasm vazifasiga mos yozing va kichik ekranda tekshiring.', 'Fayl nomini alt sifatida ko‘chirish rasm mazmunini tushuntirmaydi.')
r(11,'ul=Tartibning o‘zi muhim bo‘lmagan ro‘yxatni ifodalaydi.|ol=Qadamlar yoki reyting kabi tartib ma’noli bo‘lgan ro‘yxatni ifodalaydi.|li=Ro‘yxatning alohida bandi bo‘lib, ul yoki ol tarkibida keladi.|Ichki ro‘yxat=Boshqa ro‘yxat bandining ichiga joylashtiriladi va iyerarxiyani ko‘rsatadi.|Ro‘yxat semantikasi=Kontentni yordamchi texnologiyalarda ham bandlar sifatida anglashga yordam beradi.', '<h2>Kurs yo‘li</h2>\n<ol><li>HTML<ul><li>Teglar</li><li>Formalar</li></ul></li><li>CSS</li><li>JavaScript</li></ol>', 'Kurs bo‘limlari va ularning ikki mavzusini ichma-ich ro‘yxatga joylang.', 'Ichki ulni oldingi li bilan bog‘lamasdan tashqariga chiqarib qo‘ymang.')
r(12,'table=Qator va ustunlar bo‘yicha bog‘langan jadval ma’lumotlari uchun ishlatiladi.|tr=Jadval qatorini ifodalaydi; uning ichida sarlavha yoki oddiy kataklar keladi.|th=Sarlavha katagi; scope yordamida tegishli qator yoki ustun bilan bog‘lanishi mumkin.|td=Oddiy ma’lumot katagini ifodalaydi.|caption=Jadvalning maqsadini tushuntiradigan sarlavhani beradi.', '<table><caption>Kurs soatlari</caption>\n<thead><tr><th scope="col">Bo‘lim</th><th scope="col">Soat</th></tr></thead>\n<tbody><tr><td>HTML</td><td>28</td></tr><tr><td>CSS</td><td>36</td></tr></tbody></table>', 'Uchta bo‘lim uchun soatlar jadvalini caption, thead, tbody va scope bilan yarating.', 'Sahifaning umumiy maketini table bilan qurish jadval semantikasini noto‘g‘ri ishlatishdir.')
r(13,'header=Sahifa yoki bo‘limning kirish mazmuni va sarlavhasini guruhlaydi.|nav=Asosiy navigatsiya havolalari guruhini ifodalaydi.|main=Hujjatning asosiy mazmunini bildiradi; odatiy sahifada bitta ko‘rinadigan main bo‘ladi.|section va article=section mavzuviy guruh, article esa mustaqil tarqatish mumkin bo‘lgan mazmun uchun tanlanadi.|footer=Sahifa yoki tegishli bo‘limning yakuniy ma’lumotlarini beradi.', '<header><h1>Texnikum blogi</h1><nav><a href="#xabar">Xabarlar</a></nav></header>\n<main><article id="xabar"><h2>Ochiq dars</h2><p>Frontend loyihalari taqdimoti.</p></article></main>\n<footer>2026 — O‘quv loyiha</footer>', 'Blog sahifasini semantik bo‘limlar bilan tuzing va har tegni nima sabab tanlaganingizni yozing.', 'Har bir divni ma’nosini tekshirmasdan sectionga almashtirmang.')
r(14,'Navigatsiya=Mazmun bo‘limlari yoki sahifalar orasida o‘tish imkonini beradi.|id=Hujjat ichidagi noyob identifikator; bir sahifada takrorlanmasligi kerak.|Anchor=Fragmentli havola nishon idga olib boradi.|Sarlavha=Bo‘lim maqsadini tushuntiradi va hujjat iyerarxiyasida joy oladi.|Klaviatura=Havolalarga Tab bilan borish va Enter bilan ochish imkoniyati tekshiriladi.', '<nav aria-label="Asosiy"><a href="#kurs">Kurs</a> <a href="#savol">Savollar</a></nav>\n<main><section id="kurs"><h2>Kurs</h2><p>HTML, CSS, JS.</p></section>\n<section id="savol"><h2>Savollar</h2><p>Qanday boshlaymiz?</p></section></main>', 'Uch bo‘limli bir sahifali sayt va ishlaydigan navigatsiya tuzing.', 'Bo‘lim idsi bilan havola fragmenti mos bo‘lmasa kutilgan joyga o‘tilmaydi.')
r(15,'form=Foydalanuvchi qiymatlarini yig‘ish va yuborish jarayonini guruhlaydi.|input turi=type qiymati maydon vazifasiga mos kiritish va ayrim brauzer tekshiruvlarini tanlaydi.|name=Forma yuborilganda qiymatning kalitini belgilaydi; faqat id bunga teng emas.|required=Maydon majburiyligini brauzerga bildiradi; server tekshiruvi baribir zarur.|method=GET qiymatlari odatda URL so‘rov qismida, POST esa so‘rov tanasida yuboriladi.', '<form><label for="ism">Ism</label><input id="ism" name="ism" required>\n<label for="email">Email</label><input id="email" name="email" type="email" required>\n<button type="submit">Yuborish</button></form>', 'Ism, email va yuborish tugmasidan iborat forma tuzing; bo‘sh va noto‘g‘ri email holatini sinang.', 'Brauzerdagi required yoki email tekshiruvi ma’lumot serverda xavfsizligini kafolatlamaydi.')
r(16,'label=Maydon yorlig‘ini for va id orqali input bilan bog‘laydi; placeholder uning o‘rnini bosmaydi.|select=Oldindan belgilangan option qiymatlari orasidan tanlash imkonini beradi.|textarea=Ko‘p satrli matn kiritish maydonidir; boshlang‘ich matn teglar orasida yoziladi.|checkbox va radio=Checkbox mustaqil belgilar, bir xil name radio guruhi esa bitta tanlov uchun ishlatiladi.|button turi=form ichida type="button" oddiy amal, type="submit" esa yuborish uchun aniq ko‘rsatiladi.', '<form><label for="kurs">Kurs</label><select id="kurs" name="kurs"><option>HTML</option><option>CSS</option></select>\n<label><input type="checkbox" name="rozilik"> Shartlarni o‘qidim</label>\n<label for="izoh">Izoh</label><textarea id="izoh" name="izoh"></textarea><button type="button">Tekshirish</button></form>', 'Kurs tanlash, bitta radio guruhi, rozilik belgisi va izoh maydonini yarating.', 'Radio variantlaridagi name turlicha bo‘lsa ular bitta guruh sifatida ishlamaydi.')
r(17,'audio=Ovoz resursini sahifaga joylashtiradi; controls boshqaruvni foydalanuvchiga ko‘rsatadi.|video=Video kontent uchun element; controls, poster va o‘lcham parametrlari vazifaga mos tanlanadi.|source=Bir media elementiga format variantlarini taqdim etishi mumkin.|track=Video uchun subtitr yoki boshqa matn yo‘laklarini bog‘lashga xizmat qiladi.|Muqobil mazmun=Video tushuntirishining matni yoki transkripti axborotdan foydalanishni yengillashtiradi.', '<video controls width="320" preload="metadata">\n <source src="dars.mp4" type="video/mp4">\n Brauzeringiz videoni ko‘rsata olmadi.\n</video>\n<p>Video faylni loyiha papkasiga qo‘ying. Dars matni shu yerda beriladi.</p>', 'O‘zingizga tegishli media fayl bilan controlsli video va uning matnli bayonini yarating.', 'Fayl taqdim etilmagan bo‘lsa demo video o‘ynamaydi; bu teg noto‘g‘riligini anglatmaydi.')
r(18,'title=Brauzer varag‘i va hujjat nomini belgilaydi; h1 bilan vazifasi farqlanadi.|charset=UTF-8 kabi kodlashni belgilaydi, belgilar to‘g‘ri talqin qilinishiga yordam beradi.|viewport=Mobil ko‘rinishda sahifa kengligini qurilma kengligiga moslash uchun ishlatiladi.|description=Sahifa mazmunining qisqa metama’lumoti; qidiruv tizimi uni har doim aynan ko‘rsatishi shart emas.|lang=Hujjat tilini ko‘rsatadi va talaffuz hamda yordamchi vositalarga ma’no beradi.', '<!doctype html><html lang="uz"><head>\n<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">\n<meta name="description" content="Frontend bo‘yicha o‘quv sahifa"><title>Frontend kursi</title>\n</head><body><h1>O‘zbekcha sahifa</h1></body></html>', 'HTML hujjat head qismiga kodlash, viewport, description va mazmunli title yozing.', 'Viewport metasi bo‘lmasa responsive CSS mobil qurilmada kutilgan ko‘rinishni bermasligi mumkin.')
r(19,'CSS=Hujjatning ko‘rinishi va joylashuvini boshqaradigan uslublar tilidir.|Selektor=Qaysi elementlarga uslub qo‘llanishini tanlaydi.|Deklaratsiya=Xususiyat va qiymatdan tuzilgan uslub amalidir.|Kaskad=Bir elementga taalluqli qoidalar orasidagi ustunlikni aniqlaydi.|Meros=Ayrim xususiyatlar ota elementdan bolaga o‘tishi mumkin; hamma xususiyat meros bo‘lmaydi.', '<style>body{font-family:Arial;color:#173f34}h1{color:#176f58}</style>\n<h1>CSS bilan salom</h1><p>Matn uslubi ota elementdan kelishi mumkin.</p>', 'Bir sahifaning sarlavha va matniga alohida rang bering; qaysi xususiyat meros qolganini izohlang.', 'CSS elementning ma’nosini o‘zgartirmaydi; ko‘rinish va semantika alohida tanlanadi.')
r(20,'Inline=style atributi orqali bevosita elementga yoziladigan uslubdir.|Internal=HTMLdagi style elementi ichida beriladigan uslublardir.|External=link orqali ulanadigan alohida CSS faylida saqlanadi.|Qayta foydalanish=Bitta tashqi fayl bir nechta sahifaga bir xil uslub bera oladi.|Ulanish yo‘li=href noto‘g‘ri bo‘lsa CSS yuklanmaydi; brauzer Network vositasida tekshiriladi.', '<style>.kurs{color:#176f58}</style>\n<p class="kurs">Internal CSS namunasi</p>\n<p style="font-weight:bold">Inline CSS namunasi</p>\n<!-- Alohida loyihada: <link rel="stylesheet" href="style.css"> -->', 'Bir xil matnni uch usul bilan bezashni taqqoslang; mahalliy loyihada style.css faylini ulang.', 'Ko‘p inline uslublar keyingi tahrir va bir xillikni saqlashni qiyinlashtiradi.')
r(21,'Selektor=Uslub qo‘llanadigan elementlar to‘plamini belgilaydi.|Xususiyat=Masalan, color yoki padding ko‘rinishning o‘zgartiriladigan tomonidir.|Qiymat=Xususiyat uchun tanlangan rang, uzunlik yoki kalit so‘zdir.|Deklaratsiya bloki=Jingalak qavs ichida uslub deklaratsiyalari yoziladi.|Sintaksis=Xususiyatdan keyin ikki nuqta, deklaratsiyalar orasida nuqtali vergul ishlatiladi.', '<style>p{color:navy;font-size:18px;padding:12px}</style>\n<p>Selektor va deklaratsiya</p>', 'Uch xususiyatli CSS qoidasi yozing; selektor, xususiyat va qiymatlarni ajrating.', 'Qavs yoki ikki nuqta xatosida ayrim deklaratsiyalar e’tiborga olinmasligi mumkin.')
r(22,'Element selektori=p kabi teg nomi barcha mos elementlarni tanlaydi.|Class selektori=.card bir sinfga tegishli qayta ishlatiladigan elementlarni tanlaydi.|ID selektori=#intro hujjatdagi noyob elementni tanlash uchun ishlatiladi.|Sinflar=Bir element bir nechta classga ega bo‘lishi mumkin.|Maxsuslik=Bir xil kaskad sharoitida ID, class va teg selektorlari turli ustunlikka ega.', '<style>p{color:#333}.card{padding:16px;background:#edf4ef}#intro{font-weight:bold}</style>\n<p id="intro" class="card">Kirish</p><p class="card">Davom</p>', 'Ikki karta uchun umumiy class, faqat birinchi matn uchun ID qoidasini yarating.', 'IDni takrorlash va keraksiz yuqori maxsuslik bilan uslublarni murakkablashtirmang.')
r(23,'color=Matnning old rangini belgilaydi.|background-color=Element fon rangini belgilaydi.|HEX=Rangni o‘n oltilik kanal qiymatlari bilan ifodalaydi.|RGB=Qizil, yashil va ko‘k kanallari orqali rangni ifodalaydi.|Kontrast=Matn va fonning o‘qilishi uchun yetarli ajralishini ta’minlash kerak.', '<style>.eslatma{color:#173f34;background-color:rgb(233,243,236);padding:20px}</style>\n<p class="eslatma">O‘qilishi oson ranglar</p>', 'Ikki xil rang mavzusi yarating; matn va fonni tekshirib qaysi biri oson o‘qilishini asoslang.', 'Faqat rang bilan xato yoki muvaffaqiyat ma’nosini bermang; matnli belgi ham qo‘shing.')
r(24,'font-family=Asosiy shrift va zaxira shriftlar ro‘yxatini belgilaydi.|font-size=Matn o‘lchamini boshqaradi; rem foydalanuvchi asosiy o‘lchami bilan bog‘liq.|font-weight=Shrift qalinligini belgilaydi.|line-height=Satrlar orasidagi qator balandligini boshqaradi.|text-align=Matnning o‘z qatori ichida tekislanishini belgilaydi, element maketini emas.', '<style>body{font-family:Arial,sans-serif}h1{font-size:2rem;font-weight:700}p{font-size:1rem;line-height:1.6;text-align:left}</style>\n<h1>Kurs sarlavhasi</h1><p>Qulay o‘qiladigan asosiy matn.</p>', 'Sarlavha va asosiy matn uchun ikki darajali shrift tizimi yarating; masshtabni oshirib tekshiring.', 'Juda kichik matn va haddan tashqari zich line-height o‘qishni qiyinlashtiradi.')
r(25,'list-style=Ro‘yxat belgilarini boshqaradi; mazmunning ro‘yxat semantikasi saqlanadi.|border-collapse=Jadval katak chegaralarini birlashtirish rejimini belgilaydi.|padding=Katakdagi matn bilan uning chegarasi orasida joy beradi.|thead=Jadval sarlavhalarini guruhlaydi va alohida uslub berishga yordam beradi.|Overflow=Kichik ekranda keng jadval uchun gorizontal aylantirish qo‘llanishi mumkin.', '<style>table{border-collapse:collapse}td,th{border:1px solid #ccc;padding:12px}th{background:#edf4ef}ul{list-style-type:square}</style>\n<ul><li>HTML</li><li>CSS</li></ul><table><tr><th>Kurs</th><th>Soat</th></tr><tr><td>HTML</td><td>28</td></tr></table>', 'Ro‘yxat va jadvalni yagona dizayn bilan bezang; katak matnlari chegaraga yopishmasin.', 'Ro‘yxat belgilarini o‘chirish ma’no va navigatsiyaga qanday ta’sir qilishini hisobga oling.')
r(26,'border=Chegara qalinligi, uslubi va rangini belgilaydi.|border-radius=Burchaklarni yumaloqlashga xizmat qiladi.|outline=Ko‘pincha fokusni ajratish uchun ishlatiladi va odatda joylashuv o‘lchamiga ta’sir qilmaydi.|Chegara uslubi=solid, dashed kabi qiymatlar ko‘rinishni tanlaydi.|Fokus belgisi=Klaviatura foydalanuvchisi qayerdaligini bilishi uchun ko‘rinib turishi kerak.', '<style>.card{border:1px solid #bdd3c5;border-radius:16px;padding:20px}button:focus-visible{outline:3px solid #176f58;outline-offset:3px}</style>\n<div class="card"><h2>Kurs kartasi</h2><button>Boshlash</button></div>', 'Yumaloq burchakli karta va ko‘rinadigan fokusli tugma yarating.', 'outline:none yozib uning o‘rniga fokus ko‘rsatkichini bermaslik qulaylikni buzadi.')
r(27,'Kontent=Element ichidagi matn yoki boshqa asosiy mazmun maydonidir.|Padding=Kontent bilan chegara orasidagi ichki oraliqdir.|Border=Kontent va padding atrofidagi chegaradir.|Margin=Element tashqarisidagi qo‘shni elementlar bilan oraliqdir.|box-sizing=border-box rejimida e’lon qilingan width padding va borderni ham qamrab oladi.', '<style>*{box-sizing:border-box}.box{width:240px;padding:20px;border:4px solid #176f58;margin:16px;background:#edf4ef}</style>\n<div class="box">Border-box: tashqi chegara kengligi 240px.</div>', 'width 240px, padding 20px va border 4px uchun content-box va border-box natijalarini taqqoslang.', 'Content-box holatida yakuniy chegara kengligi 240+40+8=288px bo‘ladi; margin bunga qo‘shimcha.')
r(28,'width=Element kontent yoki tanlangan box-sizing kengligini belgilaydi.|max-width=Elementning eng katta kengligini cheklaydi.|min-height=Kontent ko‘payganda kengayish imkonini saqlagan holda minimal balandlik beradi.|Nisbiy birlik=% konteynerga, rem ildiz shriftiga, vw esa viewportga bog‘liq.|Overflow=Kontent belgilangan maydonga sig‘masa boshqarish qoidasi tanlanadi.', '<style>.container{width:90%;max-width:700px;margin:auto}.card{min-height:100px;padding:16px;background:#edf4ef}</style>\n<div class="container"><div class="card">Mos o‘lchamdagi blok</div></div>', 'Konteynerni 90% va max-width bilan cheklang; uzun matn qo‘shib balandlikni kuzating.', 'Qattiq height matnni kesishi mumkin; vazifaga qarab min-height tanlang.')
r(29,'block=Odatdagi oqimda yangi qatordan boshlanadigan blokli joylashuvdir.|inline=Matn oqimi ichida joylashadi; width odatiy inline elementda kutilgandek ishlamasligi mumkin.|inline-block=Matn oqimida turib o‘lcham va ichki oraliq olish imkonini beradi.|display:none=Elementni joylashuvdan va odatda yordamchi texnologiyalar ko‘rishidan olib tashlaydi.|visibility=hidden element ko‘rinmaydi, ammo joyi odatda saqlanadi.', '<style>.belgi{display:inline-block;padding:8px;background:#dceee2}.blok{display:block;margin:12px 0}</style>\n<span class="belgi">HTML</span><span class="belgi">CSS</span><a class="blok" href="#">Alohida qator</a>', 'Bir xil spanlarga inline, block va inline-block berib farqlarni izohlang.', 'Yashirilgan elementning klaviatura va accessibility holatini ham hisobga oling.')
r(30,'relative=Elementni odatdagi joyiga nisbatan siljitadi va oqimdagi joyini saqlaydi.|absolute=Oqimdan chiqadi va odatda eng yaqin joylashtirilgan ajdodiga nisbatan turadi.|fixed=Ko‘pincha viewportga nisbatan joylashadi, ayrim ajdod xususiyatlari bu kontekstni o‘zgartirishi mumkin.|sticky=Aylantirish chegarasida belgilangan offsetga yopishib turishi mumkin.|z-index=Qatlam tartibini kontekst ichida boshqaradi; barcha elementlarni global tartibga solmaydi.', '<style>.card{position:relative;padding:40px;border:1px solid #ccc}.badge{position:absolute;top:8px;right:8px;background:#176f58;color:white;padding:6px}</style>\n<div class="card"><span class="badge">Yangi</span>Kurs kartasi</div>', 'Karta burchagiga absolute belgi qo‘ying; ota relative bo‘lmaganda farqini tekshiring.', 'Yuqori z-index har qanday boshqa stacking contextdan ustun bo‘lishini kafolatlamaydi.')
r(31,'Normal oqim=Elementlarning odatiy hujjat tartibida joylashishidir.|Konteyner=Mazmun kengligi va ichki tartib uchun umumiy chegarani beradi.|Maket=Sahifaning katta bo‘limlari va ularning o‘zaro joylashuvini ifodalaydi.|Bo‘shliq=gap, padding va margin turli darajadagi oraliqlarni boshqaradi.|DOM tartibi=O‘qish va fokus tartibiga ta’sir qiladi; vizual tartib bilan mantiqiy mos bo‘lishi kerak.', '<style>body{margin:0}.layout{max-width:900px;margin:auto;padding:20px}header,main,footer{padding:20px;background:#edf4ef;margin-bottom:12px}</style>\n<div class="layout"><header>Sarlavha</header><main>Asosiy kontent</main><footer>Yakun</footer></div>', 'Header, asosiy kontent va footerli maket yarating; konteyner kengligini cheklang.', 'Barcha bo‘limlarni absolute bilan joylashtirish kontent o‘sganda maketni buzishi mumkin.')
r(32,'Flex konteyner=display:flex bevosita bolalar uchun bir o‘lchovli joylashuvni yoqadi.|Asosiy o‘q=flex-direction asosiy yo‘nalishni belgilaydi.|justify-content=Elementlarni asosiy o‘q bo‘ylab taqsimlaydi.|align-items=Elementlarni ko‘ndalang o‘q bo‘ylab tekislaydi.|flex-wrap=Joy yetmasa elementlarning keyingi qatorga o‘tishini boshqaradi.', '<style>.cards{display:flex;gap:16px;flex-wrap:wrap}.card{flex:1 1 180px;padding:20px;background:#edf4ef}</style>\n<div class="cards"><div class="card">HTML</div><div class="card">CSS</div><div class="card">JS</div></div>', 'Uch kartani Flexboxda joylashtiring; tor oynada yangi qatorga o‘tishini ta’minlang.', 'row va column holatida asosiy hamda ko‘ndalang o‘qlar almashishini yodda tuting.')
r(33,'Grid konteyner=display:grid qator va ustunli ikki o‘lchovli joylashuvni tashkil qiladi.|Track=Gridning qatori yoki ustuni hisoblanadi.|fr=Qolgan erkin joyning ulushini ifodalaydi.|gap=Qator va ustunlar orasidagi oraliqni belgilaydi.|minmax=Track uchun eng kichik va eng katta o‘lcham chegarasini yozadi.', '<style>.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.grid>div{padding:24px;background:#edf4ef}</style>\n<div class="grid"><div>1</div><div>2</div><div>3</div><div>4</div></div>', 'Uch ustunli grid yarating; bir kartani ikki ustun bo‘ylab yoyish qoidasini qo‘shing.', 'Gridni faqat ikki o‘lcham, Flexni faqat qator deb mutlaq cheklamang; vazifaga mosini tanlang.')
r(34,'Psevdoklass=Elementning holati yoki munosabatini tanlaydi, masalan :hover.|focus-visible=Fokus ko‘rsatkichini foydalanuvchi kiritish usuliga mos ko‘rsatishga yordam beradi.|Psevdoelement=Elementning ma’lum qismi yoki yaratilgan kontentini bezaydi.|content=::before va ::after uchun yaratiladigan kontent qiymatini beradi.|Muqobil amal=Hoverdagi muhim ma’lumot klaviatura va sensor foydalanuvchiga ham yetishi kerak.', '<style>button{padding:12px}button:hover{background:#dceee2}button:focus-visible{outline:3px solid #176f58}h2::before{content:"★ ";color:#176f58}</style>\n<h2>Kurs</h2><button>Tanlash</button>', 'Tugmaga hover va fokus uslubi, sarlavhaga bezak psevdoelement qo‘shing.', 'Muhim ko‘rsatma yoki ma’lumotni faqat CSS content ichida yashirmang.')
r(35,'transform=Elementni vizual siljitish, burish yoki masshtablashga xizmat qiladi.|transition=O‘zgaradigan xususiyat qiymatlari orasidagi o‘tishni yumshatadi.|keyframes=Animatsiyaning bosqichlaridagi uslub qiymatlarini belgilaydi.|animation=Keyframes davomiyligi va takrorlanishi kabi parametrlarni qo‘llaydi.|Reduced motion=Harakatni kamaytirishni afzal ko‘rgan foydalanuvchiga mos uslub berishga yordam beradi.', '<style>button{padding:16px;transition:transform .2s}button:hover{transform:translateY(-3px)}@media(prefers-reduced-motion:reduce){button{transition:none}}</style>\n<button>Yumshoq o‘tish</button>', 'Kartaga oddiy transform va transition qo‘shing; reduced-motion rejimida harakatni kamaytiring.', 'Barcha xususiyatga transition:all yozish o‘rniga kerakli xususiyatlarni aniq belgilang.')
r(36,'Talab=Sahifada qanday kontent va amallar bo‘lishini oldindan belgilaydi.|Semantik skelet=HTML tuzilmasini dizayndan avval ma’noli elementlar bilan tashkil qiladi.|Dizayn tizimi=Rang, shrift, oraliq va komponentlarni izchil tanlashga yordam beradi.|Qabul mezoni=Tayyor ishni aniq tekshirish mumkin bo‘lgan talabdir.|Tekshiruv=Sahifa tor ekranda, klaviatura bilan va uzun matn bilan sinab ko‘riladi.', '<style>body{font:16px Arial;margin:0}.wrap{max-width:900px;margin:auto;padding:24px}.cards{display:flex;gap:16px;flex-wrap:wrap}.card{flex:1 1 180px;background:#edf4ef;padding:24px}</style>\n<main class="wrap"><h1>IT kurslari</h1><div class="cards"><article class="card"><h2>HTML</h2><p>Tuzilma</p></article><article class="card"><h2>CSS</h2><p>Dizayn</p></article></div></main>', 'HTML va CSS bilan o‘quv markazi sahifasini yarating: navigatsiya, uch karta, aloqa qismi va footer bo‘lsin.', 'Tayyor dizaynni baholashda faqat tashqi o‘xshashlik emas, semantika va moslashuvni ham tekshiring.')
r(37,'Responsive dizayn=Kontentning turli ekran va foydalanish sharoitiga moslashishidir.|Viewport=Brauzerning sahifa ko‘rsatiladigan maydonidir.|Breakpoint=Maket o‘zgarishi zarur bo‘lgan kenglik shartidir.|Mobile first=Avval tor ekran uchun asosiy uslub, keyin kattaroq ekran uchun kengaytirish usulidir.|Mos kontent=Matn, rasm va boshqaruvlar faqat kichraytirilmaydi, foydalanishga mos qayta joylashtiriladi.', '<style>.cards{display:grid;gap:16px}@media(min-width:700px){.cards{grid-template-columns:repeat(3,1fr)}}.cards>div{background:#edf4ef;padding:24px}</style>\n<div class="cards"><div>1</div><div>2</div><div>3</div></div>', 'Bitta ustunli mobil va uch ustunli keng ekran ko‘rinishini yarating.', 'Breakpointni faqat telefon modeli nomiga emas, kontent sig‘ishiga qarab tanlang.')
r(38,'Viewport metasi=width=device-width sahifa viewportini qurilma kengligi bilan moslashtiradi.|rem=Ildiz element shrift o‘lchamiga nisbiy birlikdir.|em=Qo‘llanish kontekstiga qarab element shrift o‘lchami bilan bog‘liq bo‘ladi.|Foiz=Tanlangan xususiyat uchun tegishli kontekst o‘lchamiga nisbatan hisoblanadi.|vw=Viewport kengligining yuzdan bir ulushidir; matnni faqat vw bilan cheklash noqulay bo‘lishi mumkin.', '<meta name="viewport" content="width=device-width, initial-scale=1">\n<style>.wrap{width:90%;max-width:60rem;margin:auto}h1{font-size:clamp(1.5rem,4vw,3rem)}</style>\n<main class="wrap"><h1>Mos sarlavha</h1></main>', 'Viewport va rem birliklaridan foydalanib o‘qiladigan mobil sahifa tuzing.', 'Foydalanuvchi zoomini o‘chiradigan sozlamalar bilan matn kattalashtirishni cheklamang.')
r(39,'Media query=Sharoitga mos CSS qoidalarini faollashtiradi.|min-width=Kamida belgilangan kenglikka yetganda qoidani qo‘llaydi.|max-width=Belgilangan kenglikdan oshmagan holatni tanlaydi.|Kaskad tartibi=Bir nechta media qoidasi bir vaqtda mos kelganda ham kaskad ishlaydi.|Chegara sinovi=Breakpointning pastida, o‘zida va yuqorisida maket tekshiriladi.', '<style>.box{background:#edf4ef;padding:24px}@media(min-width:600px){.box{background:#d6e8f5}}@media(min-width:900px){.box{max-width:700px;margin:auto}}</style>\n<div class="box">Oyna kengligini o‘zgartiring.</div>', '600px va 900px chegaralarda o‘zgaradigan maket tuzing; har chegaraning ikki tomonini sinang.', 'Faqat bitta ekran o‘lchamida ko‘rish responsive yechimni tekshirish uchun yetarli emas.')
r(40,'flex-wrap=Elementlarning qatorga sig‘maganida yangi qatorga o‘tishiga ruxsat beradi.|flex-basis=Asosiy o‘qdagi boshlang‘ich o‘lchamni belgilaydi.|flex-grow=Erkin joyni elementlar orasida taqsimlash ulushidir.|flex-shrink=Joy yetishmaganda qisqarish ulushini belgilaydi.|min-width=Uzun kontentli flex bola uchun min-width:0 qisqarishga yordam berishi mumkin.', '<style>.layout{display:flex;gap:20px;flex-wrap:wrap}.item{flex:1 1 240px;min-width:0;padding:24px;background:#edf4ef}</style>\n<div class="layout"><div class="item">Asosiy qism</div><div class="item">Yon qism</div></div>', 'Ikki ustunli maketni tor ekranda ketma-ket joylashadigan qiling.', 'Uzun URL yoki so‘z minimal kenglikni oshirib sahifani tashqariga chiqarishi mumkin.')
r(41,'auto-fit=Joyga qarab takroriy ustunlarni joylashtirib, bo‘sh tracklarni yig‘ishi mumkin.|minmax=Kartalar kengligi uchun minimal va moslashuvchan maksimal qiymat beradi.|repeat=Bir xil track ta’rifini qayta yozmasdan takrorlaydi.|fr=Erkin joydan ulush ajratadi; kontent minimumlari ham ta’sir qilishi mumkin.|gap=Kartalar orasidagi oraliqni qator va ustunlarda bir xilda boshqaradi.', '<style>.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:16px}.cards>article{padding:24px;background:#edf4ef}</style>\n<div class="cards"><article>HTML</article><article>CSS</article><article>JavaScript</article></div>', 'Kartalar gridini ko‘p breakpoint yozmasdan ekran kengligiga moslashtiring.', 'Minimum track viewportdan keng bo‘lsa gorizontal chiqib ketish yuz berishi mumkin.')
r(42,'Mobil navigatsiya=Kichik maydonda havolalar va menyu boshqaruvini foydalanishga qulay joylashtiradi.|button=Menyuni ochish amali uchun semantik boshqaruvdir; havola navigatsiya uchun ishlatiladi.|aria-expanded=Yoyiladigan qismning hozirgi ochiq yoki yopiqligini bildiradi.|Fokus=Klaviatura bilan menyuga kirish va undan chiqish yo‘li saqlanadi.|Sensor boshqaruv=Tugmalar orasida yetarli joy va aniq nom bo‘lishi muhim.', '<style>nav{display:flex;gap:16px;flex-wrap:wrap}a{padding:12px;background:#edf4ef}</style>\n<nav aria-label="Asosiy"><a href="#">Bosh sahifa</a><a href="#">Kurslar</a><a href="#">Aloqa</a></nav>', 'Mobil navigatsiyani moslashtiring; yashiriladigan menyu qo‘shsangiz button va aria-expanded holatini boshqaring.', 'Faqat hover orqali ochiladigan menyu sensor va klaviatura foydalanuvchiga yetarli emas.')
r(43,'Bootstrap=Tayyor CSS sinflari va ayrim JavaScript komponentlari to‘plamidir.|Ulanish=Versiyaga mos CSS va kerak bo‘lsa JavaScript bundle ulanadi.|Container=Mazmunning responsive kengligini boshqaradi.|Utility=Oraliq, rang va joylashuv kabi bitta vazifaga yo‘naltirilgan sinflardir.|Versiya=Turli asosiy versiya hujjatlari va sinflarini aralashtirmaslik kerak.', '<!-- Bootstrap CSSni rasmiy hujjatdagi usul bilan ulang. -->\n<div class="container p-4"><h1>Bootstrap sahifa</h1><button class="btn btn-primary">Boshlash</button></div>', 'Bootstrap 5.3 hujjatidan CSS ulanishini oling va container hamda btn bilan boshlang‘ich sahifa yarating.', 'Kutubxona ulanmagan bo‘lsa class nomlarining o‘zi tayyor dizaynni yaratmaydi.')
r(44,'Container=Responsive ustunlar uchun umumiy konteynerdir.|Row=Grid ustunlarini guruhlaydi.|col=Kenglikni grid ustunlari ulushi bilan belgilaydi.|Breakpoint sinfi=col-md-6 kabi sinf ma’lum kenglikdan boshlab ishlaydi.|Gutter=Ustunlar va qatorlar orasidagi oraliqni tashkil qiladi.', '<!-- Bootstrap 5 CSS talab qilinadi. -->\n<div class="container"><div class="row g-3"><div class="col-12 col-md-6">Birinchi ustun</div><div class="col-12 col-md-6">Ikkinchi ustun</div></div></div>', 'Mobil ekranda bitta, md kenglikdan boshlab ikki ustunli Bootstrap maket yarating.', 'Ustunlarni row va container tuzilmasisiz tasodifiy joylashtirish kutilmagan oraliq beradi.')
r(45,'Navbar=Navigatsiyani tashkil etuvchi Bootstrap komponentidir.|Card=Mazmun, sarlavha va amallarni birlashtiradigan komponentdir.|Alert=Holat yoki xabarni ko‘rsatadi, lekin rang bilan cheklanmasligi kerak.|Modal=Ochiq oynada fokus va yopish imkonini boshqarish talab etiladi.|JavaScript bundle=Modal kabi interaktiv komponentlar uchun tegishli skript kerak bo‘lishi mumkin.', '<!-- Bootstrap CSS va modal uchun JS bundle kerak. -->\n<div class="card"><div class="card-body"><h2 class="card-title">HTML kursi</h2><p class="card-text">Boshlang‘ich bosqich</p><button class="btn btn-success">Tanlash</button></div></div>\n<div class="alert alert-info" role="status">Ro‘yxat ochiq.</div>', 'Navbar, uch karta va xabar komponentini yarating; modal qo‘shsangiz klaviatura bilan yopishni tekshiring.', 'Modal tashqi ko‘rinishi tayyor bo‘lsa ham fokus va Esc bilan ishlash sinovdan o‘tishi kerak.')
r(46,'Kompozitsiya=Tayyor komponentlarni bitta foydalanuvchi vazifasiga mos birlashtirishdir.|Grid=Maketni responsive ustunlarda tashkil etadi.|Moslashtirish=Bootstrap ustidan yozilgan uslublar izchil nomlanadi va kaskad tekshiriladi.|Accessibility=Semantika, yorliq, kontrast va fokus komponentdan qat’i nazar baholanadi.|Qabul sinovi=Mobil, keng ekran va klaviaturada bajariladigan vazifalar tekshiriladi.', '<!-- Bootstrap CSSni ulang. -->\n<main class="container py-4"><h1>Kurslar</h1><div class="row g-3"><article class="col-12 col-md-6"><div class="card p-3"><h2>HTML</h2><button class="btn btn-primary">Batafsil</button></div></article><article class="col-12 col-md-6"><div class="card p-3"><h2>CSS</h2><p>Dizayn asoslari</p></div></article></div></main>', 'Bootstrap yordamida o‘quv markazining responsive sahifasini yarating va beshta qabul sinovi yozing.', 'Kutubxona mavjudligi foydalanish qulayligini avtomatik kafolatlamaydi.')
def j(n,terms,code,task,pitfall,expected):r(n,terms,code,task,pitfall,expected,'js')
j(47,'JavaScript=Brauzerda hisoblash va xatti-harakatni boshqaradigan dasturlash tilidir.|Dvigatel=Kodning sintaksisini tahlil qilib, amallarni bajaradi.|Konsol=Natija, xabar va xatolarni kuzatish vositasidir.|Sinxron amal=Joriy bajarilish ketma-ketligida yakunlanadi.|Web API=DOM va fetch kabi brauzer muhiti taqdim etadigan imkoniyatlardir.', 'console.log("Salom, Frontend!");\nconsole.log(4 + 6);', 'Konsolga salomlashuv va ikkita son yig‘indisini chiqaring; JavaScript bilan DOM farqini yozing.', 'JavaScript tili bilan brauzer taqdim etadigan barcha APIlarni bir xil tushuncha deb olmang.', 'Salom, Frontend!\n10')
r(48,'script=HTMLga JavaScript ulash uchun ishlatiladi.|src=Tashqi JavaScript fayli manzilini bildiradi.|defer=Oddiy tashqi skriptni hujjat tahlilidan keyin bajarishga yordam beradi.|DOM tayyorligi=Element mavjud bo‘lmasdan unga murojaat qilish xato berishi mumkin.|Ajratish=HTML, CSS va JS fayllarini tartiblash keyingi tahrirni yengillashtiradi.', '<h1 id="salom">Boshlang‘ich matn</h1>\n<script>document.getElementById("salom").textContent="JavaScript ulandi";</script>', 'Sarlavhani JavaScript bilan o‘zgartiring; mahalliy loyihada kodni app.jsga ko‘chiring va defer bilan ulang.', 'src orqali fayl ulangan script ichiga yana alohida ishlashini kutib kod yozmang.')
j(49,'let=Qayta qiymat berish mumkin bo‘lgan blok doirasidagi bog‘lanish yaratadi.|const=Bog‘lanishga boshqa qiymat qayta berilishini cheklaydi; obyekt ichini muzlatmaydi.|var=Funksiya doirasi va ko‘tarilish xatti-harakatiga ega eskiroq e’lon usulidir.|Identifikator=Nomlash qoidalariga mos, katta-kichik harfni farqlaydigan nomdir.|O‘zlashtirish=Hisoblangan qiymatni bog‘lanishga beradi; tenglik tekshirishidan farq qiladi.', 'const narx = 5000;\nlet son = 2;\nson += 1;\nconsole.log(narx * son);', 'Narx va miqdordan to‘lovni hisoblang; o‘zgaradigan va o‘zgarmaydigan bog‘lanishni ajrating.', 'const massiv elementini o‘zgartirish bilan const nomiga boshqa massiv berish bir xil emas.', '15000')
j(50,'number=Oddiy butun va kasr sonlar uchun ishlatiladigan turdir.|string=Matn qiymati bo‘lib, bitta belgi ham shu tur bilan ifodalanadi.|boolean=true yoki false mantiqiy qiymatidir.|null va undefined=null ataylab bo‘sh qiymat, undefined esa qiymat yo‘qligini ko‘rsatadigan alohida qiymatdir.|object=Xususiyatli tuzilmalar turidir; typeof null tarixiy sabab bilan object qaytaradi.', 'console.log(typeof 12);\nconsole.log(typeof "12");\nconsole.log(typeof true);\nconsole.log(typeof undefined);\nconsole.log(typeof null);', 'Beshta turga misol yozing va typeof null natijasi nega alohida talqin qilinishini izohlang.', 'typeof null natijasini null oddiy obyekt ekanining isboti deb qabul qilmang.', 'number\nstring\nboolean\nundefined\nobject')
j(51,'Arifmetik operator=+, -, *, /, % va ** hisoblash amallarini ifodalaydi.|Qat’iy tenglik==== operandlarni majburiy turga o‘girmasdan tengligini tekshiradi.|Mantiqiy operator=&&, || va ! shartlarni birlashtirish yoki inkor qilishga xizmat qiladi.|Ustuvorlik=Amallar tartibi qavs va operator qoidalariga bog‘liq.|Satr ulash=+ satr bilan ishlaganda matn ulashga olib kelishi mumkin.', 'console.log((8 + 12) / 2);\nconsole.log("2" + 3);\nconsole.log(60 >= 0 && 60 <= 100);', 'O‘rtacha, qoldiq va 0–100 oraliq tekshiruvini yozing.', '0<=x<=100 zanjiri o‘rniga x>=0 && x<=100 yoziladi.', '10\n23\ntrue')
j(52,'console.log=Qiymatlarni konsolga chiqaradi.|prompt=Brauzerda satr yoki bekor qilinganda null beradi; har muhitda mavjud emas.|Number=Qiymatni songa o‘girishga urinadi; yaroqsiz matn NaN berishi mumkin.|Validatsiya=Kirish turini, bo‘shligini va masala cheklovini tekshiradi.|Number.isFinite=Faqat chekli number qiymati uchun true qaytaradi.', 'const xom = "12";\nconst son = Number(xom);\nconsole.log(Number.isFinite(son));\nconsole.log(son + 3);', 'Ikki kiritish satrini songa o‘girib yig‘indini toping; bo‘sh satr va noto‘g‘ri matnni rad eting.', 'Number("") 0 beradi; majburiy qiymat uchun bo‘sh kirishni alohida tekshiring.', 'true\n15')
j(53,'if=Rost shartga mos blokni bajaradi.|else if=Oldingi shart mos kelmaganda keyingi shartni tekshiradi.|else=Oldingi shartlar mos kelmagandagi yo‘lni bajaradi.|Chegara=Qaror almashadigan nuqta; tenglik kiritilishi sinov bilan aniqlanadi.|Blok=Jingalak qavs ichidagi birga boshqariladigan amallar guruhidir.', 'const ball = 60;\nif (ball < 0 || ball > 100) console.log("Xato");\nelse if (ball >= 60) console.log("O‘tdi");\nelse console.log("Qayta o‘qish");', '59,60,61 ball uchun qaror chiqaring, −1 va 101 ni yaroqsiz deb belgilang.', '>60 bilan >=60 chegarasi bir xil natija bermaydi.', 'O‘tdi')
j(54,'switch=Bitta ifoda qiymati bo‘yicha variant tanlaydi.|case=Mos kelishi tekshiriladigan variant qiymatidir.|break=Switchdan chiqib keyingi blokka o‘tadi.|default=Hech bir case mos kelmaganda bajariladigan yo‘ldir.|Fall-through=Break bo‘lmasa keyingi case tanasi ham bajarilishi mumkin.', 'const amal = "+";\nswitch (amal) {\n case "+": console.log(2 + 3); break;\n case "*": console.log(2 * 3); break;\n default: console.log("Noma’lum amal");\n}', 'Ikki son uchun to‘rt amalli kalkulyator yarating; nolga bo‘lish va noma’lum amal holatini ajrating.', 'case qiymati 1 soni bo‘lsa "1" satri bilan qat’iy teng hisoblanmaydi.', '5')
j(55,'Masala modeli=Kirish, chiqish va cheklovlarni aniq ifodalaydi.|Tarmoqlanish=Shart natijasiga qarab hisoblash yo‘lini tanlaydi.|Tenglik holati=Maksimum yoki taqqoslash masalasida alohida e’tiborga olinadi.|Test to‘plami=Oddiy, teng, chegara va yaroqsiz holatlarni qamrab oladi.|Dalil=Kutilgan hamda haqiqiy natijani solishtirish xulosaga asos bo‘ladi.', 'const a = -8, b = -3;\nconst katta = a > b ? a : b;\nconsole.log(katta);', 'Uch son maksimumini shartlar yordamida toping va teng hamda manfiy sonlar bilan sinang.', 'Maksimumni 0 dan boshlash barcha sonlar manfiy bo‘lganda xato beradi.', '-3')
j(56,'for=Boshlanish, shart va yangilashni sarlavhada birlashtiradigan sikldir.|while=Tanadan oldin davom etish shartini tekshiradi.|Iteratsiya=Siklning bitta aylanishidir.|Hisoblagich=Qaysi bosqichdaligini saqlaydigan o‘zgaruvchidir.|Tugash=Holat shartni yolg‘on qiladigan yo‘nalishda o‘zgarishi kerak.', 'let summa = 0;\nfor (let i = 1; i <= 4; i++) summa += i;\nconsole.log(summa);', '1 dan n gacha yig‘indini for va while bilan alohida yozing, natijalarni solishtiring.', 'Hisoblagichni yangilamaslik tugamaydigan sikl keltirishi mumkin.', '10')
j(57,'do...while=Avval tanani, keyin shartni bajaradi; kamida bir marta ishlaydi.|break=Joriy siklni to‘xtatadi.|continue=Qolgan tana amallarini tashlab keyingi iteratsiyaga o‘tadi.|Old shart=while dastlab yolg‘on bo‘lsa tanasi umuman ishlamaydi.|Yangilash=Continue ishlatilganda ham tugashga eltuvchi holat o‘zgarishi saqlanishi kerak.', 'for (let i = 1; i <= 5; i++) {\n if (i === 2) continue;\n if (i === 4) break;\n console.log(i);\n}', '1–10 ichida 3 ni tashlab, 8 da to‘xtaydigan sikl yozing; do...while bilan bir martalik ishni ko‘rsating.', 'While tanasidagi yangilashga yetmasdan continue qilish cheksiz siklga olib kelishi mumkin.', '1\n3')
j(58,'Akkumulyator=Takrorlash davomida yig‘iladigan natijani saqlaydi.|Yig‘indi boshlanishi=Qo‘shish uchun odatda 0 olinadi.|Ko‘paytma boshlanishi=Ko‘paytirish uchun odatda 1 olinadi.|Sikl chegarasi=Oxirgi qiymatni qamrab olish uchun < va <= farqlanadi.|Mustaqil tekshiruv=Yig‘indini formula yoki qo‘lda hisob bilan solishtirish mumkin.', 'let summa = 0, kopaytma = 1;\nfor (let i = 1; i <= 4; i++) {summa += i; kopaytma *= i;}\nconsole.log(summa, kopaytma);', '1–n yig‘indi va ko‘paytmasini hisoblang; n=1,4 va yaroqsiz kirishlar uchun test yozing.', 'Ko‘paytmani 0 dan boshlash barcha natijani 0 qilib qo‘yadi.', '10 24')
j(59,'Massiv=Tartiblangan elementlar to‘plami; JavaScript Array uzunligi o‘zgarishi mumkin.|Indeks=Element o‘rni 0 dan boshlanadi.|length=Massiv uzunligi bo‘lib, oxirgi odatiy indeks length−1 dir.|Element=Indeks orqali olinadigan qiymatdir.|Mavjud bo‘lmagan indeks=Oddiy o‘qishda undefined berishi mumkin; bu son deb ishlatilmasligi kerak.', 'const ballar = [60, 80, 90];\nconsole.log(ballar[0]);\nconsole.log(ballar.length);\nconsole.log(ballar[ballar.length - 1]);', 'Besh ball massivini yarating, birinchi va oxirgi qiymatni chiqaring hamda bir elementni yangilang.', 'i<=massiv.length sikli odatda ortiqcha indeksni ham o‘qiydi.', '60\n3\n90')
j(60,'push=Massiv oxiriga element qo‘shib yangi uzunlikni qaytaradi.|pop=Oxirgi elementni olib tashlab o‘sha qiymatni qaytaradi.|shift=Birinchi elementni olib tashlaydi.|unshift=Boshiga element qo‘shib yangi uzunlikni qaytaradi.|includes=Qiymat mavjudligini boolean sifatida tekshiradi.', 'const kurslar = ["HTML", "CSS"];\nkurslar.push("JS");\nconsole.log(kurslar.includes("JS"));\nconsole.log(kurslar.pop());\nconsole.log(kurslar);', 'Ro‘yxat boshiga va oxiriga kurs qo‘shing, olib tashlang va mavjudlikni tekshiring.', 'push qaytargan qiymatni yangi massiv deb qabul qilmang; u uzunlikdir.', 'true\nJS\n["HTML","CSS"]')
j(61,'map=Har elementdan yangi qiymat hisoblab yangi massiv qaytaradi.|filter=Shartga mos elementlardan yangi massiv yaratadi.|find=Birinchi mos elementni, topilmasa undefined qaytaradi.|forEach=Har element uchun amal bajaradi; yangi massiv qaytarmaydi.|Callback=Boshqa funksiyaga berilib u tomonidan chaqiriladigan funksiyadir.', 'const ballar = [40, 60, 80];\nconsole.log(ballar.map(x => x + 5));\nconsole.log(ballar.filter(x => x >= 60));\nconsole.log(ballar.find(x => x > 70));', 'Narxlar massivini map bilan o‘zgartiring, filter bilan ajrating va find bilan bir mahsulotni toping.', 'forEach natijasini map qaytargan massiv o‘rnida ishlatmang.', '[45,65,85]\n[60,80]\n80')
j(62,'Funksiya=Qayta ishlatiladigan hisoblash yoki amal qismini ifodalaydi.|E’lon=function nomi va parametrlar bilan vazifa ta’riflanadi.|Parametr=Funksiya ta’rifidagi kirish nomidir.|Argument=Chaqiruvda berilgan haqiqiy qiymatdir.|Chaqiruv=Funksiyani tegishli argumentlar bilan bajarishdir.', 'function salom(ism) {return "Salom, " + ism;}\nconsole.log(salom("Abdukarim"));', 'Ismni qabul qilib salomlashuv qaytaradigan funksiya yozing; uch argument bilan chaqiring.', 'Funksiya nomi bilan uni qavs orqali chaqirish bir xil emas.', 'Salom, Abdukarim')
j(63,'return=Natijani chaqirgan joyga qaytaradi va funksiyani tugatadi.|Standart parametr=Argument undefined bo‘lsa ishlatiladigan boshlang‘ich qiymatdir.|undefined=Return bajarilmagan oddiy funksiya qaytaradigan qiymatdir.|Yon ta’sir=Funksiya tashqi holat yoki ko‘rinishga o‘zgarish kiritishi mumkin.|Qayta foydalanish=Qaytarilgan qiymat boshqa ifodaga yoki funksiyaga berilishi mumkin.', 'function jami(narx, son = 1) {return narx * son;}\nconsole.log(jami(5000));\nconsole.log(jami(5000, 3));', 'Standart miqdori 1 bo‘lgan to‘lov funksiyasini yozing; argument berilgan va berilmagan holatni sinang.', 'console.log natijani ko‘rsatadi, lekin funksiyaning return qiymatini avtomatik belgilamaydi.', '5000\n15000')
j(64,'Funksional ifoda=Funksiya qiymati o‘zgaruvchiga bog‘lanishi mumkin.|Arrow function=Qisqa funksiya yozuvi; o‘z this bog‘lanishiga ega emas.|Qisqa return=Qavssiz bitta ifoda natijasi bevosita qaytariladi.|Blokli return=Jingalak qavs ishlatilsa return aniq yozilishi kerak.|Obyekt qaytarish=Qisqa arrowdan obyekt qaytarishda odatda qavs bilan o‘raladi.', 'const kvadrat = x => x * x;\nconst karta = nom => ({nom});\nconsole.log(kvadrat(4));\nconsole.log(karta("HTML"));', 'Oddiy funksiyani arrowga o‘giring; bitta ifoda va blokli ko‘rinishlarni solishtiring.', 'x => { x * x } return bo‘lmagani uchun kutilgan sonni qaytarmaydi.', '16\n{"nom":"HTML"}')
j(65,'Obyekt=Kalit va qiymatlardan tuzilgan xususiyatli ma’lumotdir.|Xususiyat=Obyektdagi nomlangan qiymatdir.|Metod=Obyekt xususiyati sifatida ishlatiladigan funksiyadir.|Nuqtali murojaat=Oldindan ma’lum nomdagi xususiyatni o‘qish usulidir.|Qavsli murojaat=Kalit o‘zgaruvchidan yoki maxsus satrdan olinganda qulaydir.', 'const kurs = {nom: "HTML", soat: 28, tavsif() {return this.nom + " kursi";}};\nconsole.log(kurs.nom);\nconsole.log(kurs["soat"]);\nconsole.log(kurs.tavsif());', 'Kurs uchun nom, soat va tavsif metodli obyekt tuzing; bitta xususiyatni yangilang.', 'Obyekt metodida this kerak bo‘lsa arrow bilan oddiy metodning farqini hisobga oling.', 'HTML\n28\nHTML kursi')
j(66,'trim=Satr chetidagi bo‘shliqlarni olib yangi satr qaytaradi.|includes=Berilgan matn bo‘lagi mavjudligini tekshiradi.|slice=Tanlangan oraliq bo‘lagini ajratadi.|split=Satrni ajratkich bo‘yicha bo‘lib massiv qaytaradi.|O‘zgarmaslik=String metodlari asl satrni joyida tahrirlamaydi; yangi natijani olish kerak.', 'const matn = "  HTML CSS JS  ";\nconst toza = matn.trim();\nconsole.log(toza.includes("CSS"));\nconsole.log(toza.split(" "));', 'Kiritilgan qidiruv matnini tozalang va kurs nomlaridan bo‘lak qidiring.', 'JavaScript length UTF-16 kod birliklarini sanaydi; ko‘rinadigan belgilar soniga doim teng emas.', 'true\n["HTML","CSS","JS"]')
j(67,'Date=Sana va vaqt bilan ishlash obyektidir; vaqt zonasi natijaga ta’sir qilishi mumkin.|Math.floor=Sonni pastki butun tomonga yaxlitlaydi.|Math.round=Eng yaqin butun qiymatga yaxlitlaydi.|Math.random=0 kiritilgan, 1 kiritilmagan oraliqda psevdotasodifiy qiymat beradi.|ISO sana=Almashuvda aniq format va vaqt zonasini ko‘rsatish chalkashlikni kamaytiradi.', 'const sana = new Date("2026-10-27T00:00:00Z");\nconsole.log(sana.getUTCFullYear());\nconsole.log(Math.floor(4.8));\nconsole.log(Math.round(4.8));', '1–6 tasodifiy butun son formulasini yozing; Date natijasida mahalliy va UTC vaqt farqini tushuntiring.', 'Math.random kriptografik maxfiy kod va parol yaratish uchun mo‘ljallanmagan.', '2026\n4\n5')
j(68,'Integratsiya=Shart, sikl, funksiya va massivni bitta masalada birlashtirishdir.|Validatsiya=Kirishlar uchun tur, oraliq va bo‘shlik talablarini tekshiradi.|Agregat=Bir nechta qiymatdan olingan umumiy ko‘rsatkichdir.|Test=Kutilgan natijaga nisbatan bajarishni tekshiradi.|Refaktoring=Tashqi natijani saqlagan holda kod tuzilishini yaxshilashdir.', 'function ortacha(sonlar) {\n if (!sonlar.length) return null;\n return sonlar.reduce((s,x) => s + x, 0) / sonlar.length;\n}\nconsole.log(ortacha([40,60,80]));', 'Ballar massivining o‘rtachasi, maksimumi va o‘tganlar sonini qaytaradigan hisobot yozing; noto‘g‘ri elementlarni rad eting.', 'Bitta oddiy testdan o‘tish barcha chegara holatlarda to‘g‘rilikni isbotlamaydi.', '60')
r(69,'DOM=Brauzer HTML hujjatini tugunlar daraxti sifatida ifodalaydigan modeldir.|Element tuguni=Teg bilan bog‘langan hujjat bo‘lagidir.|Matn tuguni=Element ichidagi matnni ifodalaydi.|document=Joriy hujjat bilan ishlashga kirish obyektidir.|Dinamik o‘zgarish=JavaScript DOMni o‘zgartirganda brauzer ko‘rinishni yangilashi mumkin.', '<h1 id="sarlavha">Eski matn</h1>\n<script>document.getElementById("sarlavha").textContent="DOM yangilandi";</script>', 'Hujjatning uch darajali DOM daraxtini chizing; sarlavha matnini JavaScript bilan yangilang.', 'HTML manba kodi bilan joriy DOM har doim aynan bir xil bo‘lib qolmaydi.')
r(70,'getElementById=Bitta id bo‘yicha element yoki null qaytaradi.|querySelector=CSS selektoriga mos birinchi element yoki null qaytaradi.|querySelectorAll=Mos elementlarning statik NodeList to‘plamini qaytaradi.|Null tekshiruvi=Element topilmagan holatni xatoga aylantirmasdan ajratadi.|Selektor sintaksisi=Class uchun nuqta, ID uchun panjara belgisi ishlatiladi.', '<p class="kurs">HTML</p><p class="kurs">CSS</p><p id="son"></p>\n<script>const kurslar=document.querySelectorAll(".kurs");document.getElementById("son").textContent="Kurslar: "+kurslar.length;</script>', 'ID, class va teg orqali elementlarni toping; yo‘q selektor natijasini tekshiring.', 'querySelectorAll natijasini bitta element deb olib textContent yozmang; kerak bo‘lsa aylantiring.')
r(71,'textContent=Matnni HTML sifatida talqin qilmasdan o‘zgartiradi.|setAttribute=Atribut qiymatini belgilaydi.|classList=Sinflarni add, remove va toggle bilan boshqaradi.|style=Elementning inline uslub xususiyatlariga murojaat beradi.|Xavfsiz matn=Tashqi ma’lumotni innerHTMLga berish o‘rniga textContent tanlash ko‘p hollarda xavfsizroqdir.', '<style>.faol{background:#dceee2;padding:20px}</style><p id="xabar">Kutilyapti</p>\n<script>const x=document.getElementById("xabar");x.textContent="Tayyor";x.classList.add("faol");x.setAttribute("title","Holat xabari");</script>', 'Xabar matni, title atributi va holat classini o‘zgartiring.', 'Ishonchsiz matnni tekshirmasdan innerHTML orqali joylashtirmang.')
r(72,'createElement=Yangi DOM elementi yaratadi.|append=Yaratilgan element yoki matnni oxiriga qo‘shadi.|remove=Elementni ota tuzilmadan olib tashlaydi.|textContent=Yangi elementning matnini belgilaydi.|Hodisa bog‘lash=Yangi yaratilgan elementga ham addEventListener ulash mumkin.', '<ul id="royxat"></ul>\n<script>const li=document.createElement("li");li.textContent="HTML";document.getElementById("royxat").append(li);</script>', 'Input qiymatidan yangi li yarating va har bir bandga o‘chirish tugmasi qo‘shing.', 'Elementni faqat yaratish uni avtomatik sahifaga qo‘shmaydi; DOMga ulash kerak.')
r(73,'click=Bosish yoki tegishli klaviatura amali natijasidagi hodisadir.|input=Maydon qiymati foydalanuvchi tomonidan o‘zgarganda yuz beradi.|change=Element turiga qarab tanlov yoki tasdiqlangan o‘zgarishni bildiradi.|submit=Forma yuborish jarayonidagi hodisadir.|addEventListener=Hodisa nomi va bajariladigan callbackni elementga bog‘laydi.', '<button id="tugma">Bosish</button><p id="holat">0 marta</p>\n<script>let son=0;document.getElementById("tugma").addEventListener("click",()=>{son++;document.getElementById("holat").textContent=son+" marta";});</script>', 'Tugmada click va matn maydonida input hodisasini qo‘llang; natijani sahifada ko‘rsating.', 'addEventListenerga callback o‘rniga funksiyani darhol chaqirish natijasini bermang.')
r(74,'Holat=Ilovaning joriy qiymatini saqlaydi.|Render=Holatni foydalanuvchi ko‘rinishiga chiqaradi.|Hodisa=Holatni yangilashga sabab bo‘ladigan harakatdir.|Chegara=Masalan, hisoblagich manfiy bo‘lmasligi kabi talabdir.|Yagona manba=Qiymatni faqat DOM matnidan tasodifan o‘qish o‘rniga holat o‘zgaruvchisida boshqarish mumkin.', '<button id="minus">−</button><output id="son">0</output><button id="plus">+</button>\n<script>let n=0;const out=document.getElementById("son");document.getElementById("plus").onclick=()=>{out.textContent=++n;};document.getElementById("minus").onclick=()=>{n=Math.max(0,n-1);out.textContent=n;};</script>', 'Qo‘shish, ayirish va tiklash tugmali hisoblagich yarating; 0 dan pastga tushmasin.', 'Ko‘rinishni yangilab holatni yangilamaslik keyingi amallarda nomuvofiqlik keltiradi.')
r(75,'Validatsiya=Qiymatning masala shartiga mosligini tekshiradi.|preventDefault=Forma hodisasining odatiy navigatsiyasini to‘xtatishi mumkin.|Trim=Majburiy matnning faqat bo‘shliqlardan iboratligini aniqlashga yordam beradi.|Xato xabari=Qaysi maydonda nima tuzatish kerakligini tushuntiradi.|Server tekshiruvi=Mijozdagi tekshiruvni chetlab o‘tish mumkinligi sabab serverda ham bajariladi.', '<form id="forma"><label>Ism <input id="ism" required></label><button>Tekshirish</button></form><p id="xabar" role="status"></p>\n<script>document.getElementById("forma").onsubmit=e=>{e.preventDefault();const ism=document.getElementById("ism").value.trim();document.getElementById("xabar").textContent=ism?"Salom, "+ism:"Ismni kiriting";};</script>', 'Ism va email formasini tekshiring; foydalanuvchiga aniq xato hamda muvaffaqiyat xabari bering.', 'Faqat alert bilan umumiy xabar chiqarish qaysi maydon xato ekanini yetarli tushuntirmasligi mumkin.')
r(76,'Menyu=Boshqaruv orqali havolalar guruhini ochib-yopishi mumkin.|Tab=Bir to‘plamdagi tegishli panelni tanlash boshqaruvidir.|Modal=Asosiy ko‘rinish ustida alohida vazifa uchun ochiladigan oynadir.|ARIA holati=Masalan aria-expanded ochiqlik, aria-selected esa tanlanganlikni bildiradi.|Fokus boshqaruvi=Modalga kirish va yopilganda avvalgi boshqaruvga qaytish tekshiriladi.', '<button id="och" aria-expanded="false" aria-controls="menu">Menyu</button><nav id="menu" hidden><a href="#">Kurslar</a></nav>\n<script>document.getElementById("och").onclick=()=>{const m=document.getElementById("menu");m.hidden=!m.hidden;document.getElementById("och").setAttribute("aria-expanded",String(!m.hidden));};</script>', 'Menyu va ikki panelni almashtiruvchi tablar yarating; tanlangan holatni ko‘rinishda va atributda yangilang.', 'Panel ko‘rinishi va aria-selected holati bir-biriga zid qolmasin.')
r(77,'localStorage=Bir origin uchun satr ko‘rinishidagi qiymatlarni brauzerda saqlash vositasidir.|setItem=Kalitga satr qiymatini saqlaydi.|getItem=Saqlangan satrni yoki topilmasa null qaytaradi.|JSON=Massiv va obyektlarni satrga aylantirib saqlashga yordam beradi.|Cheklov=Saqlash bloklanishi yoki kvota to‘lishi mumkin; maxfiy ma’lumot uchun xavfsiz ombor emas.', '<input id="ism" placeholder="Ismingiz"><button id="saqla">Saqlash</button><p id="xabar"></p>\n<script>const i=document.getElementById("ism");try{i.value=localStorage.getItem("ism")||"";}catch(e){}document.getElementById("saqla").onclick=()=>{try{localStorage.setItem("ism",i.value);document.getElementById("xabar").textContent="Saqlandi";}catch(e){document.getElementById("xabar").textContent="Saqlash mavjud emas";}};</script>', 'Ism yoki mavzu tanlovini saqlang; qayta ochish, kalit yo‘qligi va saqlash xatosini sinang.', 'Brauzer saqlashi boshqa qurilmaga avtomatik ko‘chmaydi; onlayn mashq oynasida saqlash cheklangan bo‘lishi mumkin.')
r(78,'Vazifalar ro‘yxati=Qo‘shish, ko‘rsatish va o‘chirish amallariga ega mini-ilovadir.|Holat massivi=Vazifalar ma’lumotini DOMdan alohida boshqaradi.|Render funksiyasi=Holat o‘zgarganda ko‘rinishni izchil qayta yaratadi.|Saqlash qatlami=Holatni JSON satr orqali saqlab va qayta o‘qib oladi.|Xavfsiz chiqarish=Kiritilgan matn yangi elementning textContentiga beriladi.', '<input id="vazifa"><button id="qosh">Qo‘shish</button><ul id="list"></ul>\n<script>const list=document.getElementById("list");document.getElementById("qosh").onclick=()=>{const input=document.getElementById("vazifa"),matn=input.value.trim();if(!matn)return;const li=document.createElement("li");li.textContent=matn;li.onclick=()=>li.remove();list.append(li);input.value="";};</script>', 'Vazifalar ro‘yxatini massivga ajrating; o‘chirish va localStorage orqali qayta yuklashni qo‘shing.', 'DOM elementlarini JSON sifatida saqlash o‘rniga vazifaning oddiy ma’lumotini saqlang.')
r(79,'Git=Taqsimlangan versiyalarni boshqarish tizimidir.|Repository=Loyiha tarixini saqlaydigan Git tuzilmasidir.|Commit=Tanlangan o‘zgarishlarning tarixdagi qaydidir.|Branch=Mustaqil rivojlanish yo‘lini ifodalaydi.|GitHub=Git repositorylarini joylashtirish va hamkorlik platformasidir; Gitning o‘zi bilan bir xil emas.', 'git --version\ngit status\ngit log --oneline', 'Git, commit va GitHub vazifalarini ajrating; mavjud o‘quv repository tarixini ko‘ring.', 'Git ishlashi uchun har doim GitHub yoki internet bo‘lishi shart emas.',mode='git')
r(80,'git init=Joriy loyiha uchun yangi Git repository yaratadi.|git status=Kuzatilayotgan va tayyorlangan o‘zgarishlar holatini ko‘rsatadi.|git add=Keyingi commit uchun tanlangan mazmunni staging maydoniga tayyorlaydi.|git commit=Stagingdagi o‘zgarishlarni izoh bilan qayd qiladi.|Staging=Ishchi fayllar bilan commit orasidagi tanlash bosqichidir.', 'git init\ngit status\ngit add index.html\ngit commit -m "HTML skeletini qo‘shish"\ngit status', 'Yangi o‘quv papkasida repository oching; index.htmlni stagingga qo‘yib mazmunli commit yarating.', 'git adddan keyin fayl yana o‘zgarsa yangi tahrir avtomatik stagingga kirmaydi.',mode='git')
r(81,'Remote=Masofadagi repository uchun nomlangan manzildir.|origin=Ko‘p loyihalarda asosiy remote uchun ishlatiladigan kelishilgan nomdir.|push=Mahalliy commitlarni masofadagi tegishli branchga yuboradi.|pull=Masofadagi o‘zgarishlarni olib birlashtirish jarayonini bajaradi.|Autentifikatsiya=Hisobning ruxsati talab qilinishi mumkin; token va kalitlar kodga qo‘shilmaydi.', 'git remote -v\ngit branch --show-current\n# Remote manzilni o‘zingizga tegishli repository bilan belgilang.\n# git remote add origin REPOSITORY_MANZILI\n# git push -u origin BRANCH_NOMI', 'O‘zingizning o‘quv repositoryingizni GitHub bilan bog‘lang; pushdan keyin fayllar ko‘rinishini tekshiring.', 'Tasodifiy branch nomi yoki begona remote manziliga push qilmang; avval remote va branchni tekshiring.',mode='git')
r(82,'README=Loyihaning maqsadi, ishga tushirish tartibi va imkoniyatlarini tushuntiradi.|.gitignore=Hali kuzatilmayotgan fayllarni mos qoidalar orqali e’tibordan chetda qoldiradi.|Tarix=git log commitlar ketma-ketligini ko‘rsatadi.|git diff=O‘zgarishlarni solishtirishga yordam beradi.|Commit izohi=Qanday mazmunli o‘zgarish qilinganini tushuntirishi kerak.', 'git status\ngit diff\ngit log --oneline\n# .gitignorega misollar: node_modules/ va .env\n# README: maqsad, fayllar, ishga tushirish, sinovlar.', 'README va .gitignore yarating; stagingdan oldin diffni ko‘rib, ikki mazmunli commit qiling.', '.gitignore ilgari commit qilingan maxfiy ma’lumotni tarixdan avtomatik o‘chirmaydi.',mode='git')
j(83,'JSON=Ma’lumot almashish uchun matn formatidir.|JSON.stringify=JavaScript qiymatini JSON satrga aylantiradi.|JSON.parse=JSON matnini qiymatga aylantiradi; noto‘g‘ri matnda xato beradi.|Format talabi=JSON kalitlari va satrlarida qo‘shtirnoq ishlatiladi, funksiya yozilmaydi.|Tekshirish=Parse muvaffaqiyati ma’lumot kerakli tuzilmada ekanini avtomatik kafolatlamaydi.', 'const matn = \'{"nom":"HTML","soat":28}\';\nconst kurs = JSON.parse(matn);\nconsole.log(kurs.nom);\nconsole.log(JSON.stringify(kurs));', 'Kurslar massivini JSONga aylantiring, qayta o‘qing va majburiy maydonlarni tekshiring.', 'JSON JavaScript obyekt literalining barcha imkoniyatlarini qabul qilmaydi.', 'HTML\n{"nom":"HTML","soat":28}')
r(84,'API=Dasturlar orasidagi muloqot interfeysidir.|HTTP so‘rovi=Metod, URL, sarlavha va mumkin bo‘lgan tanadan tuziladi.|HTTP javobi=Holat kodi, sarlavhalar va mumkin bo‘lgan ma’lumot tanasini beradi.|REST=Resurslar va bir xil interfeys kabi tamoyillarga asoslangan arxitektura uslubidir.|Status=200,404 va500 kabi kodlar javob ma’nosini tushuntirishga yordam beradi.', '<h1>API so‘rov-javobi</h1><p>GET /api/kurslar → 200 va JSON ma’lumoti</p><p>Topilmagan resurs → 404</p>', 'Kurslarni olish, bitta kursni ko‘rish va yangi kurs yaratish uchun metod hamda resurs yo‘lini taklif qiling.', 'Har qanday HTTP API REST tamoyillariga to‘liq mos deb hisoblanmaydi.')
r(85,'fetch=So‘rovni boshlaydi va Response uchun Promise qaytaradi.|Response.ok=200–299 holat kodlari uchun muvaffaqiyatni bildiradi.|json=Javob tanasini JSON sifatida o‘qishning asinxron usulidir.|HTTP xatosi=404 yoki500 fetch Promisesini o‘z-o‘zidan rad etmaydi; ok tekshiriladi.|CORS=Brauzerning originlar orasidagi resurs o‘qish qoidalaridir; mijoz kodi server ruxsatini majburlamaydi.', '<button id="ol">Olish</button><pre id="natija"></pre>\n<script>document.getElementById("ol").onclick=async()=>{try{const r=await fetch("https://jsonplaceholder.typicode.com/todos/1");if(!r.ok)throw new Error("HTTP "+r.status);const d=await r.json();document.getElementById("natija").textContent=JSON.stringify(d,null,2);}catch(e){document.getElementById("natija").textContent=e.message;}};</script>', 'Ochiq o‘quv APIdan bitta resurs oling; ok, JSON va xatoni alohida tekshiring.', 'Internet yoki tashqi API mavjud bo‘lmasa xato chiqishi tabiiy; muvaffaqiyatni soxta ma’lumot bilan almashtirmang.')
r(86,'Promise=Kelajakdagi muvaffaqiyat yoki xato natijasini ifodalaydi.|then=Muvaffaqiyatli natija bilan keyingi amalni bog‘laydi.|catch=Rad etilgan holat yoki oldingi zanjirdagi xatoni ushlaydi.|finally=Muvaffaqiyat va xatodan qat’i nazar yakuniy tozalashga xizmat qiladi.|Zanjir=Keyingi then avvalgi qaytargan qiymat yoki Promisega bog‘liq bo‘ladi.', '<pre id="natija"></pre>\n<script>Promise.resolve(["HTML","CSS"]).then(k=>k.join(", ")).then(matn=>{document.getElementById("natija").textContent=matn;}).catch(e=>{document.getElementById("natija").textContent=e.message;});</script>', 'Promise zanjirida ma’lumotni o‘zgartiring, xato holatini ham ataylab yarating va catchni tekshiring.', 'then ichidagi Promise yoki qiymatni qaytarmaslik keyingi bosqichni noto‘g‘ri natijaga olib kelishi mumkin.')
r(87,'async=Funksiya natijasini Promise sifatida beradi.|await=Async funksiya bajarilishini Promise hal bo‘lguncha shu nuqtada davom ettirmay turadi.|try...catch=Await paytidagi rad etilish yoki sinxron xatoni ushlaydi.|Ketma-ketlik=Ikki mustaqil awaitni ketma-ket yozish ularni parallel boshlamaydi.|Promise.all=Mustaqil ishlarni birgalikda kutishda qo‘llanishi mumkin.', '<p id="xabar">Kutilyapti</p>\n<script>async function boshlash(){try{const kurslar=await Promise.resolve(["HTML","CSS"]);document.getElementById("xabar").textContent=kurslar.join(" / ");}catch(e){document.getElementById("xabar").textContent=e.message;}}boshlash();</script>', 'then zanjirini async/awaitga o‘giring va xatoni try...catch bilan ko‘rsating.', 'await barcha brauzer ishlarini to‘liq muzlatadi degan talqin noto‘g‘ri; u tegishli async oqimga ta’sir qiladi.')
r(88,'Ma’lumot modeli=APIdan kelgan maydonlar va kutilgan turlarni belgilaydi.|Render=Tekshirilgan ma’lumotdan DOM elementlarini yaratadi.|createElement=Natijalar uchun semantik elementlarni yaratadi.|textContent=Tashqi matnni HTMLga aylantirmasdan ko‘rsatadi.|Bo‘sh javob=Yaroqli lekin elementlari yo‘q to‘plam alohida xabar olishi kerak.', '<ul id="kurslar"></ul>\n<script>const data=[{nom:"HTML"},{nom:"CSS"}];const list=document.getElementById("kurslar");for(const kurs of data){const li=document.createElement("li");li.textContent=kurs.nom;list.append(li);}</script>', 'O‘quv API yoki berilgan JSONdan kartalar yarating; yo‘q maydon va bo‘sh ro‘yxatni tekshiring.', 'API matnini tekshirmasdan innerHTMLga kiritish kod talqin qilinishiga olib kelishi mumkin.')
r(89,'Loading=So‘rov davom etayotganini foydalanuvchiga bildiradi.|Error=So‘rov yoki ma’lumotni qayta ishlash muvaffaqiyatsizligini tushuntiradi.|Empty=So‘rov muvaffaqiyatli, ammo mos natija yo‘qligini bildiradi.|Retry=Xatodan keyin foydalanuvchiga qayta urinish imkonini beradi.|Holat modeli=Loading, success, empty va error bir-biriga zid ko‘rinmasligi kerak.', '<button id="ol">Yuklash</button><p id="holat" role="status"></p>\n<script>document.getElementById("ol").onclick=async()=>{const h=document.getElementById("holat");h.textContent="Yuklanmoqda…";try{const data=await Promise.resolve([]);h.textContent=data.length?"Tayyor":"Natija topilmadi";}catch(e){h.textContent="Xato: "+e.message;}};</script>', 'Loading, bo‘sh natija, muvaffaqiyat va xato holatini alohida sinab ko‘rsating.', 'Bo‘sh ro‘yxatni ulanish xatosi deb, xatoni esa muvaffaqiyat deb ko‘rsatmang.')
r(90,'Qidiruv=Foydalanuvchi kiritishiga mos ma’lumotni tanlaydi.|Filtrlash=Shartga mos elementlardan yangi to‘plam hosil qiladi.|Normalizatsiya=Qidiruvni trim va kelishilgan harf registri bilan bir xillashtirishi mumkin.|Poyga holati=Oldin boshlangan so‘rov keyin tugab yangi natijani almashtirib qo‘yishi mumkin.|Bekor qilish=AbortController yoki so‘rov identifikatori eskirgan natijani cheklashga yordam beradi.', '<input id="q" placeholder="Kurs qidiring"><ul id="list"></ul>\n<script>const kurslar=["HTML","CSS","JavaScript"];function render(){const q=document.getElementById("q").value.trim().toLowerCase();document.getElementById("list").replaceChildren(...kurslar.filter(x=>x.toLowerCase().includes(q)).map(x=>{const li=document.createElement("li");li.textContent=x;return li;}));}document.getElementById("q").oninput=render;render();</script>', 'Ro‘yxatni APIdan oling, qidiruv maydoni bilan filtrlang, loading va xato holatini ko‘rsating.', 'Har klavish bosilganda keraksiz ko‘p so‘rov yubormaslik uchun talabga mos debounce qo‘llanishi mumkin.')
r(91,'Texnik topshiriq=Loyiha kimga qanday vazifani bajarishda yordam berishini va cheklovlarini belgilaydi.|Auditoriya=Interfeysdan foydalanadigan insonlar va ularning ehtiyojlaridir.|Foydalanuvchi oqimi=Maqsadga erishishdagi qadamlar ketma-ketligidir.|Funksional talab=Tizim bajarishi kerak bo‘lgan aniq amalni ifodalaydi.|Qabul mezoni=Talab bajarilganini kuzatib tekshirish mumkin bo‘lgan shartdir.', '<h1>Loyiha topshirig‘i</h1><ul><li>Auditoriya: texnikum o‘quvchilari</li><li>Maqsad: kurs tanlash</li><li>Amal: kursni qidirish va ko‘rish</li><li>Mezon: mos natija va bo‘sh holat ko‘rsatiladi</li></ul>', 'O‘quv markazi, portfolio yoki kutubxona loyihasini tanlang. Besh funksional talab, uch sifat talabi va besh qabul mezoni yozing.', 'Chiroyli va tez bo‘lsin kabi umumiy istakni o‘lchab bo‘ladigan mezonga aylantiring.')
r(92,'Sayt xaritasi=Sahifalar va ularning bog‘lanishini ko‘rsatadigan rejalashtirish hujjatidir.|Navigatsiya=Asosiy sahifalar va foydalanuvchi yo‘llarini ochiq qiladi.|Kontent iyerarxiyasi=Muhim mazmun va bo‘ysunuvchi bo‘limlar tartibini ko‘rsatadi.|Wireframe=Sahifa qismlarining sodda joylashuv chizmasidir.|Izchillik=Bir xil navigatsiya va atamalar sahifalar bo‘ylab saqlanadi.', '<nav><a href="#bosh">Bosh sahifa</a> <a href="#kurslar">Kurslar</a> <a href="#aloqa">Aloqa</a></nav>\n<main><section id="bosh"><h1>O‘quv markazi</h1></section><section id="kurslar"><h2>Kurslar</h2></section><section id="aloqa"><h2>Aloqa</h2></section></main>', 'Tanlangan loyiha uchun sahifalar xaritasi va bosh sahifa wireframeini tuzing; barcha havola yo‘llarini belgilang.', 'Sahifalar xaritasi bilan tayyor dastur yoki vizual dizayn bir xil hujjat emas.')
def project(n,base,task,pitfall):
 import copy
 L[n]=copy.deepcopy(L[base]);L[n]['task']=task;L[n]['pitfall']=pitfall;L[n]['project']=True
project(93,13,'Tanlangan loyiha uchun to‘liq index.html skeleti yarating: lang, meta, sarlavha, nav, main, bo‘limlar va footer bo‘lsin. Bo‘lim sarlavhalari kontent xaritasiga mos kelsin.','Semantik skeletni tayyorlagach dizayn qo‘shing; faqat ko‘rinish uchun teg tanlamang.')
project(94,14,'Loyihadagi barcha sahifa va bo‘limlar uchun navigatsiya yarating. Bosh sahifaga qaytish, fragment va tashqi havolalarni sinov jadvaliga kiriting.','Fayl nomidagi katta-kichik harf hostingda muhim bo‘lishi mumkin; mahalliy ishlagan havolani nashrda ham tekshiring.')
project(95,24,'Loyihaga asosiy ranglar, ikki shrift darajasi, oraliqlar va tugma uslubidan iborat dizayn tizimi qo‘llang. Uslublarni tashqi CSSga ajrating.','Har sahifada tasodifiy rang va shrift ishlatish o‘rniga bir xil qoidalarni saqlang.')
project(96,41,'Loyihaning asosiy maketini Grid, karta yoki navigatsiyasini Flexbox bilan yarating. Tor va keng ekranda natijani izohlang.','Faqat bitta texnologiyadan majburan foydalanish o‘rniga vazifaga mos joylashuv tanlang.')
project(97,10,'Loyihaga rasmlar, uchta kurs kartasi va zarur bo‘lsa jadval joylashtiring. Har ma’lumotli rasmga mazmunli alt va o‘lcham bering.','Rasm mavjud bo‘lmaganida ham kontent mazmuni tushunarli qolishini tekshiring.')
project(98,39,'Loyihani 360px, 768px va 1280px kengliklarda tekshiring. Gorizontal chiqish, o‘qilmaydigan matn va bosish qiyin tugmalarni tuzating.','Bu kengliklar sinov misollari; haqiqiy moslashuv ularning orasidagi o‘lchamlarda ham ishlashi kerak.')
project(99,45,'Loyihangizning bitta qismini Bootstrap bilan takomillashtiring; navbar, card yoki alert tanlang. Ulanish versiyasi va o‘z CSSingiz ustunligini hujjatlashtiring.','Bootstrapning bir nechta versiyasini bir vaqtda ulash va mos kelmaydigan atributlardan foydalanishdan saqlaning.')
project(100,65,'Loyiha ma’lumotini obyekt va massivlarda tashkil qiling. Hisoblash yoki filtrlash funksiyalarini DOMdan alohida yozib kamida beshta kirish bilan sinang.','Biznes hisobini faqat tugma ichidagi uzun callbackga yashirish testlashni qiyinlashtiradi.')
project(101,73,'Loyihaga ishlaydigan menyu, tugmalar va input hodisalarini ulang. Holat, ko‘rinish va aria atributlari birga yangilansin.','Bir hodisaga takroriy listener qo‘shilib qolsa bitta bosishda ikki marta amal bajarilishi mumkin.')
project(102,75,'Loyiha formasida majburiy maydonlar, email va bo‘shliq tekshiruvini yarating. Xato qaysi maydonda ekanini ko‘rsating va forma ma’lumotini saqlab qoling.','Haqiqiy shaxsiy ma’lumot yig‘masdan o‘quv namunalari bilan sinang; mijoz tekshiruvi server o‘rnini bosmaydi.')
project(103,78,'Loyiha holatini oddiy ma’lumot modeliga ajrating. JSON orqali saqlash va tiklashni qo‘shing; buzilgan JSON va saqlash mavjud bo‘lmagan holatni boshqaring.','Saqlangan ma’lumot tuzilmasi o‘zgarsa eski yozuvni o‘qish uchun versiya yoki tekshirish qoidasi kerak bo‘lishi mumkin.')
project(104,89,'Tashqi o‘quv APIni loyihaga ulang. Loading, muvaffaqiyat, bo‘sh va xato holatlari hamda qayta urinish boshqaruvini yarating.','API javob tuzilmasi, ruxsat va tarmoq holatini tekshiring; maxfiy API kalitini frontendga yozmang.')
project(105,82,'Loyihani Git orqali bosqichma-bosqich saqlang. README, .gitignore, mazmunli commitlar va o‘zingizga tegishli GitHub repository havolasini tayyorlang.','Commitdan oldin git diff va git status bilan aynan qaysi fayllar ketayotganini tekshiring.')
r(106,'Funksional sinov=Talab qilingan amal kutilgan natija berishini tekshiradi.|Chegara sinovi=Bo‘sh, minimal, maksimal va noodatiy kirishlarni tekshiradi.|Responsive sinov=Turli kenglik va kattalashtirishda kontentni tekshiradi.|Accessibility sinovi=Klaviatura, yorliq, fokus va ma’noli tuzilmani baholaydi.|Regressiya=Tuzatishdan keyin avval ishlagan amallarni qayta sinashdir.', '<h1>Sinov jurnali</h1><table><tr><th>Holat</th><th>Kutilgan</th><th>Natija</th></tr><tr><td>Bo‘sh qidiruv</td><td>Barcha kurslar</td><td>Tekshiring</td></tr><tr><td>Mos kelmagan so‘z</td><td>Natija topilmadi</td><td>Tekshiring</td></tr></table>', 'Loyihangiz uchun kamida o‘nta test yozing: oddiy, chegara, mobil, klaviatura va tarmoq xatolari bo‘lsin. Uchta xatoni dalil bilan tuzating.','Faqat konsolda xato yo‘qligi barcha funksiyalar talabga mos ekanini isbotlamaydi.')
r(107,'Deployment=Loyiha fayllarini foydalaniladigan hosting muhitiga chiqarishdir.|Build=Vosita ishlatilsa ishlab chiqarishga mos chiqish fayllarini yaratadi.|Nisbiy yo‘l=Nashr yo‘li va papka nomlari bilan mos kelishi kerak.|HTTPS=Tarmoq aloqasini himoyalaydi; xizmatning barcha jihati xavfsizligini kafolatlamaydi.|Qayta tekshirish=Nashrdagi havola, rasm, API va navigatsiya mahalliy holatdan alohida sinaladi.', '<h1>Nashrga tayyorlik</h1><ol><li>Fayllar va yo‘llarni tekshirish</li><li>Build talabini aniqlash</li><li>Hostingga joylash</li><li>Havola, rasm va funksiyalarni tekshirish</li></ol>', 'O‘zingizga tegishli o‘quv loyihani hostingga joylang yoki nashr yo‘riqnomasini tayyorlang; URL va qabul sinovlarini hisobotga kiriting.', 'API kaliti, .env yoki shaxsiy ma’lumotni ommaviy statik fayllarga qo‘shmang.')
r(108,'HTML=Kontentning tuzilishi va ma’nosini belgilaydi.|CSS=Ko‘rinish va responsive joylashuvni boshqaradi.|JavaScript=Hisoblash va xatti-harakatni tashkil etadi.|DOM va API=DOM hujjatni boshqaradi, API esa dasturlar muloqotini ta’minlaydi.|Git=Loyiha tarixini boshqaradi va hamkorlikda o‘zgarishlarni kuzatishga yordam beradi.', '<h1>Frontend bilim xaritasi</h1><ul><li>HTML → semantika va forma</li><li>CSS → maket va responsive</li><li>JS → mantiq va hodisa</li><li>API → ma’lumot</li><li>Git → tarix</li></ul>', 'Besh texnologiyaning loyihadagi vazifasini yozing; har biri uchun bitta xato va tuzatish misolini ko‘rsating.', 'Atamalarni yoddan sanash bilan ularni ishlaydigan loyihada qo‘llashni bir xil baholamang.')
project(109,36,'Mustaqil mini-loyiha yarating: semantik HTML, responsive CSS, kamida ikki JavaScript amali, validatsiyali forma va hujjatlashtirilgan sinovlar bo‘lsin. API yoki saqlashni vazifaga mos qo‘shing.','Namunani shunchaki ko‘chirish o‘rniga talabga mos mustaqil yechim va qarorlar izohini taqdim eting.')
r(110,'Taqdimot=Loyihaning auditoriyasi, vazifasi va yechimini dalil bilan tushuntiradi.|Demo=Oldindan tayyorlangan foydalanuvchi oqimini amalda ko‘rsatadi.|Baholash mezoni=Natijani oldindan ma’lum talablar bilan solishtiradi.|Refleksiya=Qiyinchilik, tuzatish va keyingi yaxshilashni tahlil qiladi.|Hisobot=Kod, ishga tushirish tartibi, sinovlar va manbalarni birlashtiradi.', '<h1>Loyiha himoyasi</h1><ol><li>Muammo va auditoriya</li><li>Asosiy foydalanuvchi oqimi</li><li>Responsive va klaviatura sinovi</li><li>Xato va tuzatish</li><li>Keyingi rivojlanish</li></ol>', 'Loyihani taqdim eting va o‘zingiz baholang: talab va semantika 20, dizayn/responsive 20, funksiyalar 25, sinov va qulaylik 20, Git/README va taqdimot 15 ball.', 'Faqat chiroyli demo bilan cheklanmay, xato va cheklovlarni ham ochiq ko‘rsating.')
assert set(L)==set(range(1,111))

